  static const int YACA_KEY_TYPE_IV = 2;

  /// RSA public key
  static const int YACA_KEY_TYPE_RSA_PUB = 3;

  /// RSA private key
  static const int YACA_KEY_TYPE_RSA_PRIV = 4;

  /// Digital Signature Algorithm public key
  static const int YACA_KEY_TYPE_DSA_PUB = 5;

  /// Digital Signature Algorithm private key
  static const int YACA_KEY_TYPE_DSA_PRIV = 6;

  /// Diffie-Hellman public key
  static const int YACA_KEY_TYPE_DH_PUB = 7;

  /// Diffie-Hellman private key
  static const int YACA_KEY_TYPE_DH_PRIV = 8;

  /// Elliptic Curve public key (for DSA and DH)
  static const int YACA_KEY_TYPE_EC_PUB = 9;

  /// Elliptic Curve private key (for DSA and DH)
  static const int YACA_KEY_TYPE_EC_PRIV = 10;

  /// Digital Signature Algorithm parameters
